import hashlib
from flask import Flask, request, jsonify
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64
import struct
import time

app = Flask(__name__)

# Legacy session management - key loaded from environment
SESSION_KEY = os.environ.get('SESSION_KEY', 'a' * 32).encode()[:32]

def decrypt_session(ciphertext_b64):
    """Decrypt session token using AES-CBC with PKCS7 padding.
    Returns plaintext bytes or raises ValueError on padding error."""
    try:
        raw = base64.b64decode(ciphertext_b64)
    except Exception:
        raise ValueError("Invalid base64")

    if len(raw) < 32:  # IV (16) + at least one block (16)
        raise ValueError("Ciphertext too short")

    iv = raw[:16]
    ciphertext = raw[16:]

    if len(ciphertext) % 16 != 0:
        raise ValueError("Invalid ciphertext length")

    cipher = AES.new(SESSION_KEY, AES.MODE_CBC, iv)
    plaintext_padded = cipher.decrypt(ciphertext)

    # VULNERABLE: unpad raises ValueError with different message
    # than the checks above, creating a padding oracle
    plaintext = unpad(plaintext_padded, 16, style='pkcs7')
    return plaintext


def parse_session(plaintext):
    """Parse session: first 8 bytes = user_id, next 8 = expiry timestamp, rest = role"""
    if len(plaintext) < 17:
        raise ValueError("Session too short")
    user_id = struct.unpack('>Q', plaintext[:8])[0]
    expiry = struct.unpack('>Q', plaintext[8:16])[0]
    role = plaintext[16:].decode('utf-8')
    return {'user_id': user_id, 'expiry': expiry, 'role': role}


@app.route('/api/profile', methods=['GET'])
def get_profile():
    """Protected endpoint requiring valid session token."""
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401

    try:
        plaintext = decrypt_session(token)
    except ValueError as e:
        error_msg = str(e)
        # VULNERABILITY: Different error messages leak padding validity
        if 'Padding' in error_msg or 'padding' in error_msg:
            return jsonify({'error': 'Authentication failed', 'code': 'E_CRYPTO'}), 403
        else:
            return jsonify({'error': 'Authentication failed', 'code': 'E_FORMAT'}), 400

    try:
        session = parse_session(plaintext)
    except (ValueError, struct.error):
        return jsonify({'error': 'Invalid session data'}), 403

    if session['expiry'] < time.time():
        return jsonify({'error': 'Session expired'}), 401

    # After decryption, fetch user data
    return jsonify({
        'user_id': session['user_id'],
        'role': session['role'],
        'message': f"Welcome back, user {session['user_id']}"
    })


@app.route('/api/admin/command', methods=['POST'])
def admin_command():
    """Admin endpoint that executes maintenance commands."""
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401

    try:
        plaintext = decrypt_session(token)
        session = parse_session(plaintext)
    except (ValueError, struct.error):
        return jsonify({'error': 'Authentication failed'}), 403

    if session['role'] != 'admin':
        return jsonify({'error': 'Insufficient privileges'}), 403

